import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, join, resolve, sep } from "node:path";
import type { MediaStorage } from "../ports/external.js";

/** Keys are generated by the server (farmId/uuid.ext); anything else is refused to rule out path tricks. */
const SAFE_KEY = /^[0-9a-f-]{36}\/[0-9a-f-]{36}\.(jpg|png|webp)$/;

export function memoryMediaStorage(): MediaStorage & { objects: Map<string, { bytes: Buffer; contentType: string }> } {
  const objects = new Map<string, { bytes: Buffer; contentType: string }>();
  return {
    objects,
    async put(key, bytes, contentType) {
      objects.set(key, { bytes: Buffer.from(bytes), contentType });
    },
    async get(key) {
      return objects.get(key) ?? null;
    },
    async delete(key) {
      objects.delete(key);
    },
  };
}

/** Development storage on local disk. Production uses an S3-compatible adapter behind the same port. */
export function localDiskMediaStorage(rootDir: string): MediaStorage {
  const root = resolve(rootDir);
  const pathOf = (key: string) => {
    if (!SAFE_KEY.test(key)) throw new Error("Invalid storage key");
    const p = resolve(join(root, key));
    if (!p.startsWith(root + sep)) throw new Error("Invalid storage key");
    return p;
  };
  return {
    async put(key, bytes, contentType) {
      const p = pathOf(key);
      await mkdir(dirname(p), { recursive: true });
      await writeFile(p, bytes);
      await writeFile(`${p}.type`, contentType);
    },
    async get(key) {
      const p = pathOf(key);
      try {
        const [bytes, contentType] = await Promise.all([readFile(p), readFile(`${p}.type`, "utf8")]);
        return { bytes, contentType };
      } catch {
        return null;
      }
    },
    async delete(key) {
      const p = pathOf(key);
      await rm(p, { force: true });
      await rm(`${p}.type`, { force: true });
    },
  };
}
